//! Speed: one generated file of at least 5 MB, extracted and merged with every unit translated.
//! Run in release for the real number:
//!   cargo test -p bilingua-mif --release --test speed -- --nocapture
//! Set BILINGUA_MIF_SPEED_OUT to a path to keep the generated file (tests/tools/speed_locos.py reads it).
mod common;
use bilingua_mif::Mif;
use bilingua_model::*;
use std::time::Instant;

pub fn generate() -> String {
    let mut s = String::with_capacity(6_000_000);
    s.push_str("<MIFFile 2019> # Generated by FrameMaker 2019\n<Units Ucm >\n<TextFlow\n <TFTag `A'>\n");
    let mut i = 0;
    while s.len() < 5_300_000 {
        let body = match i % 4 {
            0 => format!(
                "   <String `Press the button number {i} to save your work, then '>\n   <Font\n    <FTag `Emphasis'>\n   > # end of Font\n   <String `close'>\n   <Font\n    <FTag `'>\n   > # end of Font\n   <String `  the window.'>\n"
            ),
            1 => format!(
                "   <String `Welcome to '>\n   <Variable\n    <VariableName `Product'>\n   > # end of Variable\n   <String `, version {i}.'>\n   <Char Tab>\n   <String `Back\\\\slash \\Qquoted\\q \\> done'>\n   <FNote 3>\n"
            ),
            2 => format!(
                "   <String `\u{65e5}\u{672c}\u{8a9e}\u{306e}\u{30c6}\u{30ad}\u{30b9}\u{30c8} {i} \u{3067}\u{3059}\u{3002}'>\n   <Char HardReturn>\n   <String `\u{3053}\u{308c}\u{306f}\u{9577}\u{3044}\u{6587}\u{7ae0}\u{3067}\u{3059}\u{3002}'>\n"
            ),
            _ => format!(
                "   <String `See '>\n   <XRef\n    <XRefName `Heading & Page'>\n    <XRefSrcText `1001: Heading1: Getting started'>\n   > # end of XRef\n   <String `Getting started on page {i}'>\n   <XRefEnd >\n   <String `.'>\n"
            ),
        };
        s.push_str(&format!(
            " <Para\n  <Unique {i}>\n  <PgfTag `Body'>\n  <ParaLine\n   <TextRectID {}>\n{body}  > # end of ParaLine\n > # end of Para\n",
            i % 9
        ));
        i += 1;
    }
    s.push_str("> # end of TextFlow\n# End of MIFFile\n");
    s
}

#[test]
fn large_file() {
    let text = generate();
    assert!(text.len() >= 5_000_000);
    if let Ok(p) = std::env::var("BILINGUA_MIF_SPEED_OUT") {
        std::fs::write(p, &text).unwrap();
    }
    let o = ExtractOptions {
        limits: Some(Limits { max_units: 10_000_000, ..Limits::default() }),
        ..Default::default()
    };
    let t0 = Instant::now();
    let mut doc = Mif.extract(text.as_bytes(), &o).unwrap();
    let t_extract = t0.elapsed();
    let n = doc.units.len();
    let t1 = Instant::now();
    for (i, u) in doc.units.iter_mut().enumerate() {
        u.segments[0].target = vec![Inline::text(format!("T{i} \"q\" translated"))];
    }
    let out = Mif.merge(&doc).unwrap();
    let t_merge = t1.elapsed();
    let untouched = Mif.merge(&Mif.extract(text.as_bytes(), &o).unwrap()).unwrap();
    assert!(untouched == text.as_bytes());
    println!(
        "Bilingua mif: {:.1} MB, {} units, extract {} ms, translate+merge {} ms, extract+merge {} ms",
        text.len() as f64 / 1e6,
        n,
        t_extract.as_millis(),
        t_merge.as_millis(),
        (t_extract + t_merge).as_millis()
    );
    let again = Mif.extract(&out, &o).unwrap();
    assert_eq!(again.units.len(), n);
}
